WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (96::BIGINT, 'el mejor profesor de mi vida, es un amor, es un papichulo rico mi amor de verdad con usted no tengo una sola queja. ya enserio el mae es buen profe en todos los aspectos y muy abierto reclamos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-04T00:00:00+00:00'::TIMESTAMPTZ, '658974a7823044f118a6a0f63a45f7981cfdefbfc590f36c7bf018262789c19e'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (96::BIGINT, 'Es muy agradable y es gracioso, pero a veces da ejemplos muy raros, no se le entiende lo que escribe en la pizarra, pero es muy abierto a explicar las veces que sea, realmente quiere que entiendas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'a43aa80b4459b8982d5c1033a9817999479c62667dd45e36c0be633b082487ca'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (96::BIGINT, 'Buen profe pero sí da la materia un toque rápido, hace varios quices no tan difíciles y muestra mucho interés por enseñar'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'd80c72bcb0dee3841acca7ee4406f91988c8c61c0d16d6be196196d956a52f7c'::TEXT, ARRAY[568]::BIGINT[]),
    (96::BIGINT, 'Como persona está bien, como profesor es malísimo, explica mal, da ejemplos confusos y va demasiado rápido. Si sus bases son buenas medio va a entender si no mejor ni vaya, a mitad de semestre ya no va a ver a nadie en sus clases. Pésima idea ponerlo a dar bases que va a ocupar para el resto de la U'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-23T00:00:00+00:00'::TIMESTAMPTZ, '4ec8ed76df02233ce9989541e96d86a0fb5d5d4cd71fd390953c765fd3f9cc63'::TEXT, ARRAY[568]::BIGINT[]),
    (96::BIGINT, 'Yo les juro que es el mejor profesor para química, explica muy bien y está interesado en que todos sigan el ritmo de la clase, atiende dudas y nunca tiene problema en devolverse, hace varios quices pero eso es bueno porque uno se prepara muy bien para el examen, siempre explica con una sonrisa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-06T00:00:00+00:00'::TIMESTAMPTZ, '6425b2fc28bea9ed8c506ea243a78c07e390b88b93d4ad1ebc6254c2a7f87de1'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'Buen profe, suele explicar mucho, más de lo necesario pero lo hace. No hace la clase tan monótona como otros. Califica duro en lab pero es porque desea que los estudiantes se pongan las pilas. Sea honesto y él le recompensará su sinceridad y trabajo duro.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '6838d66f6b114719f0c964ed0f9d6a5d99faafd605d794ba492c5ea3b2446a4e'::TEXT, ARRAY[613]::BIGINT[]),
    (96::BIGINT, 'Es muy buen ser humano y se nota que ama la química. Siempre esta dispuesto a ayudar y es sumamente compresivo. Le interesa mucho el procedimiento de los cálculos y lo reconoce en caso que en la respuesta haya un error. Si uno de pierde un poco en clase se puede reforzar con los pdf que sube'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, '64e3ff03ba195e8b9e9bc22e88a90e3a103a8a68704f6da7471ccd4e20a0f466'::TEXT, ARRAY[568]::BIGINT[]),
    (96::BIGINT, 'Excelente profe, lo llevé virtual el semestre pasado y yo le preguntaba varas que vimos hace semanas y las explicaba con todo el gusto'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'cad929382fd9ec0b47e6e133f159fc7710cfdd1eeee8352d700f803a0a39391c'::TEXT, ARRAY[568]::BIGINT[]),
    (96::BIGINT, 'Cuesta un poco entenderlo, hace mucho desorden cuando está explicando y al final usted no entiende nada, a menos de que sea muy bueno en química no le recomiendo que matricule con él'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Pocos exámenes']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '30a71cf1ad97fb570cd0e81dd78789fd8cca0c5a14786516daa41ea0730d66b8'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'En modalidad virtual demasiado desordenado con todo, cambia las evaluaciones a última hora.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'e65f5136cd45f4205524d1c3d920dc8a394987a5206f22e874227641d555c39e'::TEXT, ARRAY[3222]::BIGINT[]),
    (96::BIGINT, 'Excelente profesor, se nota que ama lo que hace si le gusta la química definitivamente este profe es para usted, virtualmente todo muy sencillo deja pocos quizes pero muy fáciles si le pone el mínimo esfuerzo va a pasar y le va a gustar el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '9e01d40880531fdda05b8079a8b085c3779960f59b5fdf8a3aed2d23eb93a6da'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'Califica suave los informes.Quices fáciles. Es muy estricto con la bitácora. Ayuda al estudiante si él ve que realmente se esforzó. Muy comprensivo. A veces un poco desordenado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-16T00:00:00+00:00'::TIMESTAMPTZ, '43eb95f4f8d1ba9499a18d5fcfa90cd74d5ced5e831f647aa20659bc4063fda2'::TEXT, ARRAY[613]::BIGINT[]),
    (96::BIGINT, 'Excelente profesor, tiene mucha paciencia y ayuda mucho. Súper recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-16T00:00:00+00:00'::TIMESTAMPTZ, '6bd9063d0893da63d5de322831f50695170d9efb260f630bb8604f42aea7a85c'::TEXT, ARRAY[568]::BIGINT[]),
    (96::BIGINT, 'El mae es un toquecillo desordenado pero explica excelente. Aparte ayuda en consulta. Con él se puede pasar el curso y sacar buena nota para subir el ponderado!'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-12T00:00:00+00:00'::TIMESTAMPTZ, '4ebc318c89c34ba0761e7c6b1fcd4e6f5d01093f2c1ab34be3334eca162a8fe6'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '6124a5523d54225a48691b6910d2eaea3b6f42828cee90426f8a5882b74bce8f'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'Digamos que ese mae hizo que química 2 fuera la menor de mis preocupaciones al final del semestre. A veces las explicaciones son un poco confusas (sobre todo con lo desordenado que es) pero al final le agarrás el toque. Y las practicas de clase son muy imporantes para los quices y el examen.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '342bfc840a7d4f5e545f164a648873dddf4d6703eb223d33f38fdc6dbe8d9136'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'Excelente profesor. Clases entretenidas, es muy pura vida y ayuda en quices. Hace mucha práctica por lo que se llega muy bien preparado al examen. 100% recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-07T00:00:00+00:00'::TIMESTAMPTZ, '60de166991f57d99de4f033fa2c8c437621e9b21a650340a632204a962b59323'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (96::BIGINT, 'es muy bueno, es paciente y se preocupa por que el estudiante aprenda, es un poco desordenado en la pizarra pero si prestas atención a la clase logras entenderle. si lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '67dba4769e3056947e03bb687f25e063a6832707fd017438bc79a7d9ff14446e'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'Starbird es un profesor muy buen profesor y persona. Si usted le pregunta cualquier cosa, él le contesta hasta que a usted le quede claro y también le explica asuntos importantes del desarrollo ingenieril, hace quices constantemente y califica los exámenes justamente. Es muy buena gente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '6b384572d30b6f2d7045df9eb85aa0d436ada4622f1f57e69fc18ec38b65a3f0'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'Es un excelente profesor y excelente persona, es algo (muy) desordenado en la pizarra, pero ayuda mucho y saca el tiempo necesario para aclarar dudas. Hace quices de 20 minutos cuando faltan 5 o menos para salir! No lo recomiendo si es antes del almuerzo (Porque te quedas sin tiempo para comer)'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-04-17T00:00:00+00:00'::TIMESTAMPTZ, '6562f40fffd359c36e5e30bea5e0e58336c558c541803bc5d8e302c9049328ae'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (96::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-21T00:00:00+00:00'::TIMESTAMPTZ, '3f6e567b9fd6c1295c8c8aa5346fb20dfb588137029dc64a122084c669a6dd13'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (96::BIGINT, '¡Es increíble! No solo hace todo lo posible para que cada estudiante pase el curso, logra que obtengas el interés por la materia, por la química inclusive; es notable que se preocupa porque toda la materia quede claro, ¡EN VERDAD SE PREOCUPA! Recomendado 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'eda37d21b01d98b3e87d54673301dc0be2638cdec166287eeedc7db99b588366'::TEXT, ARRAY[614]::BIGINT[]),
    (96::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '7cbe5fd9730715e2c4d59afe46558878fbb9395dfc99710c6e2e4fa7ad5797fb'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (96::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'db33632636e55549d327c7be23a89851aee5434b156332a93f8ae1c9fad3ed26'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (96::BIGINT, 'Exc profesor y persona no solo me ayudo montones en mi primer laboratorio hace años, tambien para investigacion y proyectos super buena nota'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f25b925c3a16600e63dd2283ce34bfb60484e029724c16ff4a276819103effb9'::TEXT, ARRAY[613]::BIGINT[]),
    (96::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '0ab8f82295115e36a102551e073256093e2bb7eaacbe9a83fffb1d8d3cf0e3a9'::TEXT, ARRAY[614]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
